const SHELL_CACHE = 'orion-shell-' + VERSION;
const ASSET_CACHE = 'orion-assets';   // long-lived; pruned by path, not by VERSION
const ROOT = new URL('./', self.location).pathname;

self.addEventListener('install', (e) => {
  e.waitUntil((async () => {
    const c = await caches.open(SHELL_CACHE);
    // cache: 'reload' bypasses the HTTP cache so a new version never precaches stale files
    await Promise.all(SHELL.map(async (p) => { try { const r = await fetch(new Request(p, { cache: 'reload' })); if (r.ok) await c.put(p, r); } catch { /* offline install of one file: fetch handler will retry */ } }));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('orion-shell-') && k !== SHELL_CACHE) await caches.delete(k);
    if (ASSETS.length) {
      const keep = new Set(ASSETS.map((p) => new URL(p, self.location).pathname));
      const c = await caches.open(ASSET_CACHE);
      for (const req of await c.keys()) if (!keep.has(new URL(req.url).pathname)) await c.delete(req);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin || !url.pathname.startsWith(ROOT)) return;
  const rel = url.pathname.slice(ROOT.length);
  if (rel.startsWith('data/textures/') || rel.startsWith('data/galaxies/')) { e.respondWith(cacheFirst(req)); return; }
  e.respondWith(staleWhileRevalidate(req, e));
});

async function cacheFirst(req) {
  const c = await caches.open(ASSET_CACHE);
  const hit = await c.match(req, { ignoreSearch: true });
  if (hit) return hit;
  const r = await fetch(req);
  if (r.ok && r.status === 200) c.put(req, r.clone()).catch(() => {});
  return r;
}

async function staleWhileRevalidate(req, e) {
  const c = await caches.open(SHELL_CACHE);
  const hit = await c.match(req, { ignoreSearch: req.mode === 'navigate' });
  const net = fetch(req).then((r) => { if (r.ok && r.status === 200) c.put(req, r.clone()).catch(() => {}); return r; });
  if (hit) { e.waitUntil(net.catch(() => {})); return hit; }
  return net;
}
